`$json = Get-Content 'artifacts/ui_tree.json' -Raw | ConvertFrom-Json
function FindGrid(`$node) {
    if (`$node.Children.Count -ge 3 -and `$node.Type -eq 'Grid') {
        return `$node
    }
    foreach (`$c in `$node.Children) {
        `$res = FindGrid `$c
        if (`$res) { return `$res }
    }
    return `$null
}
`$g = FindGrid `$json
